pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        // Restrict to callers that are the Bank contract itself which passes supportsToken
        // The Bank contract's address is deterministic when created below.
        // We'll deploy a Bank to act as msg.sender; the modifier supportsToken checks msg.sender's supportsToken return.
        vm.assume(actor != address(0));

        // Deploy a fresh Bank contract. Its supportsToken returns the correct hash.
        Bank bank = new Bank();

        // Actor must be the bank address to pass supportsToken
        vm.assume(actor == address(bank));

        // Assert the actor has no balance (modifier hasNoBalance)
        vm.assume(c.tokenBalance(actor) == 0);

        // The modifier _nonReentrant requires _locked == false initially
        // We cannot directly check _locked (public), but fresh contract has it false.

        // Execute airDrop as the bank
        vm.prank(actor);
        try c.airDrop() { 
            // If it succeeded, actor's balance must be exactly 20.
            assertEq(c.tokenBalance(actor), 20);
        } catch {
            // If it reverted, we accept; property only applies on success.
            // To keep a single assert approach we can invert: we need the rule to hold for *every* input that doesn't revert.
            // A simpler universal rule: after any call (revert or not), if balance changed it must be 20.
            // But we'll use the try/catch success path assertion.
            assertTrue(true); // dummy to pass when reverts, but we need a single assert for all paths.
            // Instead, we capture revert: the rule we can assert universally is:
            // If airDrop does NOT revert, then balance must be 20.
            // So we can assert: (success => balance == 20) which is equivalent to (!success || balance == 20).
        }
    }
}

// We need the Bank contract defined here to deploy it in test.
contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

