pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 numCalls, address actor) public {
        // restrict number of calls to a reasonable range
        numCalls = uint8(bound(numCalls, 1, 10));
        // actor must be a distinct address with enough balance to satisfy hasNoBalance
        vm.assume(actor != address(0));
        // ensure actor starts with zero balance in tokenBalance
        vm.assume(c.tokenBalance(actor) == 0);
        // actor must be a contract that supports the token to pass supportsToken modifier
        // we use a pre-deployed Bank contract that always returns the correct hash
        // actor must have code, so we etch a Bank contract
        vm.assume(actor.code.length > 0);
        // deploy a Bank instance and etch its code onto the actor address
        Bank bank = new Bank();
        vm.etch(actor, address(bank).code);

        // try to call airDrop numCalls times
        bool allSucceeded = true;
        for (uint8 i = 0; i < numCalls; i++) {
            bool ok;
            vm.prank(actor);
            try c.airDrop() {
                ok = true;
            } catch {
                ok = false;
            }
            if (!ok) {
                allSucceeded = false;
                break;
            }
        }

        // After all calls, check that _locked is false (via public getter)
        // Reference: always false after a completed call. Bug: true after first call, so subsequent calls fail,
        // and _locked remains true.
        bool lockedAfter = c._locked();
        // In reference, all calls succeed and _locked is false.
        // In buggy, at most one call succeeds, and _locked is true after that.
        // So property: if all calls succeeded, _locked must be false.
        // This holds for reference, but buggy violates it when numCalls > 1.
        assertTrue(!(allSucceeded && lockedAfter));
    }
}

