        bytes32 expectedToken = keccak256(abi.encodePacked("Nu Token"));
        (bool okSupports, bytes memory data) = address(new Bank()).call(abi.encodeWithSignature("supportsToken()"));
        require(okSupports, "Bank call failed");
        bytes32 support = abi.decode(data, (bytes32));
        require(support == expectedToken, "Token support mismatch");
        // Deploy a Bank-like contract at the caller address that returns the same support
        vm.etch(caller, address(new Bank()).code);
        // Record initial balance
        uint256 balBefore = c.tokenBalance(caller);
        // Call airDrop as the caller
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("airDrop()"));
        // Observe final balance
        uint256 balAfter = c.tokenBalance(caller);
        // Assert: either revert OR balance increased by exactly 20; never both, never other changes.
        // The buggy version allows success when balBefore == 0 (reference requires revert), thus for balBefore == 0 the assertion fails because ok is true and balAfter == balBefore + 20.
        assertTrue((!ok && balAfter == balBefore) || (ok && balAfter == balBefore + 20));
    }
}

