        // actor must have a supportsToken that returns the correct hash
        // We deploy a helper contract that provides the required supportsToken
        Helper helper = new Helper();
        // We need actor to be a contract with the correct supportsToken, so we use the helper
        // But the call must originate from actor, so we set actor's code to helper's code
