            bool reentrantSucceeded;
            vm.prank(actor);
            try c.airDrop() {
                reentrantSucceeded = true;
            } catch {
                reentrantSucceeded = false;
            }
            // The second call must revert for the reference contract (reentrancy protection)
            // The mutant lacks the lock, so the second call succeeds
            assertTrue(!reentrantSucceeded);
        } catch {
            // first call reverted, nothing to test
        }
    }
